# tier, topic, title, prompt, hint, solution, explanation, ordered(bool)
P=[
# ---------- EASY ----------
("easy","aggregation","Policies per product","Count policies per product, highest count first.","GROUP BY product, ORDER BY the count.",
"SELECT product, COUNT(*) AS n FROM policies GROUP BY product ORDER BY n DESC, product;","Basic GROUP BY. Tie-break on product so the order is deterministic.",True),
("easy","aggregation","Total premium by state","Return each state and total written premium (rounded to 2 dp).","SUM + ROUND.",
"SELECT state, ROUND(SUM(premium),2) AS total_premium FROM policies GROUP BY state ORDER BY state;","Aggregate then round — rounding before summing loses precision.",True),
("easy","filtering","Open claims over $3k reserve","List claim_id, reserve_amount for OPEN claims whose reserve exceeds 3000.","WHERE with two conditions.",
"SELECT claim_id, reserve_amount FROM claims WHERE status='OPEN' AND reserve_amount>3000 ORDER BY claim_id;","Straight filter. Watch string case on status.",True),
("easy","joins","Claims with product","For each claim show claim_id, product and paid_amount.","Join claims to policies on policy_id.",
"SELECT c.claim_id, p.product, c.paid_amount FROM claims c JOIN policies p ON p.policy_id=c.policy_id ORDER BY c.claim_id;","INNER JOIN on the foreign key.",True),
("easy","joins","Customers with no claims","Return names of customers who have never had a claim.","LEFT JOIN through policies to claims and keep NULLs — or NOT EXISTS.",
"SELECT name FROM customers cu WHERE NOT EXISTS (SELECT 1 FROM policies p JOIN claims c ON c.policy_id=p.policy_id WHERE p.customer_id=cu.customer_id) ORDER BY name;","Anti-join. NOT EXISTS is NULL-safe; NOT IN breaks if the subquery returns a NULL.",True),
("easy","aggregation","Average claim severity by cause","Average incurred (paid + reserve) per cause, 2 dp, sorted by average desc.","Incurred = paid_amount + reserve_amount.",
"SELECT cause, ROUND(AVG(paid_amount+reserve_amount),2) AS avg_incurred FROM claims GROUP BY cause ORDER BY avg_incurred DESC;","Severity = loss per claim.",True),
("easy","having","States with 3+ customers","States that have at least 3 customers.","HAVING filters after grouping.",
"SELECT state, COUNT(*) AS n FROM customers GROUP BY state HAVING COUNT(*)>=3 ORDER BY state;","WHERE filters rows, HAVING filters groups.",True),
("easy","dates","Claims reported same week","Claims where report_date is within 7 days of loss_date. Return claim_id and lag_days.","julianday(a)-julianday(b) in SQLite (DATEDIFF elsewhere).",
"SELECT claim_id, CAST(julianday(report_date)-julianday(loss_date) AS INT) AS lag_days FROM claims WHERE julianday(report_date)-julianday(loss_date)<=7 ORDER BY claim_id;","Date arithmetic is dialect-specific: Databricks datediff(end,start), Snowflake DATEDIFF('day',start,end).",True),
("easy","dates","Quotes per month","Count quotes per month (YYYY-MM).","strftime('%Y-%m', quote_date).",
"SELECT strftime('%Y-%m',quote_date) AS month, COUNT(*) AS quotes FROM quotes GROUP BY month ORDER BY month;","date_trunc('month', d) in Databricks/Postgres.",True),
("easy","case","Bind rate by product","Quote-to-bind rate per product as a percentage with 1 dp.","AVG of a 0/1 flag is a rate.",
"SELECT product, ROUND(100.0*AVG(bound),1) AS bind_rate_pct FROM quotes GROUP BY product ORDER BY product;","AVG(flag) = SUM(flag)/COUNT(*). Multiply by 100.0 to avoid integer division.",True),
("easy","case","Bucket premiums","Count policies in buckets: '<1000', '1000-2499', '2500+'.","CASE WHEN inside GROUP BY.",
"SELECT CASE WHEN premium<1000 THEN '<1000' WHEN premium<2500 THEN '1000-2499' ELSE '2500+' END AS bucket, COUNT(*) AS n FROM policies GROUP BY bucket ORDER BY bucket;","CASE evaluates top-down, so the second branch only sees premium>=1000.",True),
("easy","distinct","Distinct customers with orders","How many distinct users have placed a complete order?","COUNT(DISTINCT ...).",
"SELECT COUNT(DISTINCT user_id) AS buyers FROM orders WHERE status='complete';","COUNT(DISTINCT) vs COUNT(*) is a classic interview trap.",False),
("easy","joins","Employee and manager","Show each employee name with their manager's name (NULL for the top).","Self join employees to employees.",
"SELECT e.name, m.name AS manager FROM employees e LEFT JOIN employees m ON m.emp_id=e.manager_id ORDER BY e.emp_id;","LEFT JOIN keeps the CEO with no manager.",True),
("easy","aggregation","Highest salary per department","Max salary per dept.","GROUP BY dept.",
"SELECT dept, MAX(salary) AS max_salary FROM employees GROUP BY dept ORDER BY dept;","To get the *person*, you need a window function (see medium).",True),
("easy","null","Coalesce referrals","List customer name and referrer's customer_id, showing 0 when not referred.","COALESCE.",
"SELECT name, COALESCE(referred_by,0) AS referrer FROM customers ORDER BY customer_id;","COALESCE returns the first non-NULL argument.",True),
("easy","filtering","Active policies in CA or TX","policy_id of ACTIVE policies in CA or TX.","IN list.",
"SELECT policy_id FROM policies WHERE status='ACTIVE' AND state IN ('CA','TX') ORDER BY policy_id;","Parenthesize OR conditions; IN avoids the precedence bug.",True),
("easy","aggregation","Refund share","Percent of orders refunded (1 dp).","SUM(CASE WHEN ...)/COUNT(*).",
"SELECT ROUND(100.0*SUM(CASE WHEN status='refunded' THEN 1 ELSE 0 END)/COUNT(*),1) AS refund_pct FROM orders;","Conditional aggregation.",False),
("easy","union","All customer touchpoint dates","One column of distinct dates when any customer either got a quote or had a policy start, earliest 5.","UNION dedupes, UNION ALL doesn't.",
"SELECT d FROM (SELECT quote_date AS d FROM quotes UNION SELECT effective_date FROM policies) ORDER BY d LIMIT 5;","UNION removes duplicates (costly on big data); use UNION ALL when you know rows are distinct.",True),
("easy","aggregation","Users per country and plan","Count users by country and plan.","GROUP BY two columns.",
"SELECT country, plan, COUNT(*) AS n FROM users GROUP BY country, plan ORDER BY country, plan;","Multi-column grouping.",True),
("easy","subquery","Above-average premium","Policies with premium above the overall average.","Scalar subquery.",
"SELECT policy_id, premium FROM policies WHERE premium>(SELECT AVG(premium) FROM policies) ORDER BY policy_id;","Scalar subquery evaluated once.",True),
# ---------- MEDIUM ----------
("medium","window","Rank policies by premium within state","Return state, policy_id, premium, and dense rank of premium (highest=1) within state.","DENSE_RANK() OVER (PARTITION BY ... ORDER BY ... DESC).",
"SELECT state, policy_id, premium, DENSE_RANK() OVER (PARTITION BY state ORDER BY premium DESC) AS rnk FROM policies ORDER BY state, rnk, policy_id;","ROW_NUMBER: unique; RANK: gaps after ties; DENSE_RANK: no gaps.",True),
("medium","top-n","Top 2 earners per department","Name, dept, salary of the top 2 salaries per dept.","Rank in a CTE then filter rnk<=2 (QUALIFY in Databricks/Snowflake).",
"WITH r AS (SELECT name, dept, salary, ROW_NUMBER() OVER (PARTITION BY dept ORDER BY salary DESC) rn FROM employees) SELECT name, dept, salary FROM r WHERE rn<=2 ORDER BY dept, salary DESC;","Top-N per group = window rank + filter. You cannot filter a window in WHERE of the same SELECT.",True),
("medium","running","Running premium by effective date","For each policy in effective_date order, show cumulative premium.","SUM() OVER (ORDER BY ... ROWS UNBOUNDED PRECEDING).",
"SELECT policy_id, effective_date, premium, ROUND(SUM(premium) OVER (ORDER BY effective_date, policy_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW),2) AS running FROM policies ORDER BY effective_date, policy_id;","Explicit ROWS frame avoids RANGE tie behavior.",True),
("medium","lag","Renewal premium change","For each renewal (a customer's next policy of the same product), show customer_id, policy_id, prior premium, and % change (1 dp).","LAG(premium) OVER (PARTITION BY customer_id, product ORDER BY effective_date).",
"WITH x AS (SELECT customer_id, policy_id, premium, LAG(premium) OVER (PARTITION BY customer_id, product ORDER BY effective_date) AS prev FROM policies) SELECT customer_id, policy_id, prev, ROUND(100.0*(premium-prev)/prev,1) AS pct_change FROM x WHERE prev IS NOT NULL ORDER BY customer_id, policy_id;","Rate-change analysis on renewals — a core pricing metric.",True),
("medium","dedup","Dedupe logins","Return each user's distinct login dates count vs raw rows count.","COUNT(*) vs COUNT(DISTINCT login_date).",
"SELECT user_id, COUNT(*) AS raw_rows, COUNT(DISTINCT login_date) AS distinct_days FROM logins GROUP BY user_id ORDER BY user_id;","Detect duplication before you fix it.",True),
("medium","dedup","Keep latest claim per policy","For each policy keep only the most recently reported claim (tie-break on claim_id desc).","ROW_NUMBER() ... = 1.",
"WITH r AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY policy_id ORDER BY report_date DESC, claim_id DESC) rn FROM claims) SELECT policy_id, claim_id, report_date FROM r WHERE rn=1 ORDER BY policy_id;","The canonical dedup pattern (CDC, late-arriving duplicates).",True),
("medium","joins","Loss ratio by product","Loss ratio = sum(paid+reserve)/sum(premium) per product, 3 dp. Aggregate claims and premium separately first.","Fan-out trap: joining policies to claims duplicates premium.",
"WITH prem AS (SELECT product, SUM(premium) p FROM policies GROUP BY product), loss AS (SELECT p.product, SUM(c.paid_amount+c.reserve_amount) l FROM claims c JOIN policies p ON p.policy_id=c.policy_id GROUP BY p.product) SELECT prem.product, ROUND(COALESCE(l,0)/p,3) AS loss_ratio FROM prem LEFT JOIN loss ON loss.product=prem.product ORDER BY prem.product;","Aggregate each fact to the shared grain before joining (drill-across). Here premium is written, not earned — say so in an interview.",True),
("medium","pivot","Claims by cause pivot","One row per product with columns water, fire, theft, injury, collision = claim counts.","SUM(CASE WHEN cause='Water' THEN 1 ELSE 0 END).",
"SELECT p.product, SUM(CASE WHEN cause='Water' THEN 1 ELSE 0 END) water, SUM(CASE WHEN cause='Fire' THEN 1 ELSE 0 END) fire, SUM(CASE WHEN cause='Theft' THEN 1 ELSE 0 END) theft, SUM(CASE WHEN cause='Injury' THEN 1 ELSE 0 END) injury, SUM(CASE WHEN cause='Collision' THEN 1 ELSE 0 END) collision FROM claims c JOIN policies p ON p.policy_id=c.policy_id GROUP BY p.product ORDER BY p.product;","Conditional aggregation pivot works everywhere; Databricks also has PIVOT.",True),
("medium","window","Share of state premium","Each policy's premium as % of its state's total (1 dp).","SUM(premium) OVER (PARTITION BY state).",
"SELECT policy_id, state, ROUND(100.0*premium/SUM(premium) OVER (PARTITION BY state),1) AS pct_of_state FROM policies ORDER BY state, policy_id;","Window aggregates keep row detail — no self-join needed.",True),
("medium","dates","Monthly revenue with MoM growth","Monthly complete-order revenue and MoM % growth (1 dp).","Aggregate in CTE, then LAG.",
"WITH m AS (SELECT strftime('%Y-%m',order_date) mon, SUM(amount) rev FROM orders WHERE status='complete' GROUP BY mon) SELECT mon, ROUND(rev,2) rev, ROUND(100.0*(rev-LAG(rev) OVER (ORDER BY mon))/LAG(rev) OVER (ORDER BY mon),1) AS mom_pct FROM m ORDER BY mon;","Aggregate first, window second.",True),
("medium","self-join","Customers who referred someone in another state","Referrer name, referee name where states differ.","Self join customers on referred_by.",
"SELECT r.name AS referrer, c.name AS referee FROM customers c JOIN customers r ON r.customer_id=c.referred_by WHERE r.state<>c.state ORDER BY referrer, referee;","Self joins model relationships within one entity.",True),
("medium","funnel","Event funnel","Count distinct users reaching each step: visit, signup, add_to_cart, purchase.","COUNT(DISTINCT CASE WHEN event_type=... THEN user_id END).",
"SELECT COUNT(DISTINCT CASE WHEN event_type='visit' THEN user_id END) visit, COUNT(DISTINCT CASE WHEN event_type='signup' THEN user_id END) signup, COUNT(DISTINCT CASE WHEN event_type='add_to_cart' THEN user_id END) add_to_cart, COUNT(DISTINCT CASE WHEN event_type='purchase' THEN user_id END) purchase FROM events;","Simple funnel. A strict funnel requires steps in order (see hard).",False),
("medium","funnel","Quote funnel by month","Per quote month: quotes, binds, bind rate %.","Same as bind rate, grouped by month.",
"SELECT strftime('%Y-%m',quote_date) mon, COUNT(*) quotes, SUM(bound) binds, ROUND(100.0*SUM(bound)/COUNT(*),1) bind_pct FROM quotes GROUP BY mon ORDER BY mon;","Quote metrics are day-to-day work at an insurtech.",True),
("medium","subquery","Customers above their state average premium","Customers whose total premium exceeds the average customer total in their state.","Two levels: customer totals, then state average via window.",
"WITH t AS (SELECT c.customer_id, c.name, c.state, SUM(p.premium) tot FROM customers c JOIN policies p ON p.customer_id=c.customer_id GROUP BY c.customer_id, c.name, c.state), s AS (SELECT *, AVG(tot) OVER (PARTITION BY state) st_avg FROM t) SELECT name, state, ROUND(tot,2) tot FROM s WHERE tot>st_avg ORDER BY state, name;","Correlated-subquery problems are cleaner as window aggregates.",True),
("medium","window","Second highest salary","Return the second highest distinct salary overall (NULL if none).","DENSE_RANK = 2, or MAX where < MAX.",
"SELECT MAX(salary) AS second_highest FROM employees WHERE salary<(SELECT MAX(salary) FROM employees);","Classic. DENSE_RANK version generalizes to Nth.",False),
("medium","dates","Days since last claim per customer","For each customer with claims: last loss_date and days from it to 2026-06-30.","MAX then julianday diff.",
"SELECT p.customer_id, MAX(c.loss_date) last_loss, CAST(julianday('2026-06-30')-julianday(MAX(c.loss_date)) AS INT) days_since FROM claims c JOIN policies p ON p.policy_id=c.policy_id GROUP BY p.customer_id ORDER BY p.customer_id;","Recency features feed pricing and fraud models.",True),
("medium","window","Moving 3-order average","Per user, 3-order moving average of amount (current + 2 prior), 2 dp.","AVG() OVER (... ROWS BETWEEN 2 PRECEDING AND CURRENT ROW).",
"SELECT user_id, order_id, order_date, ROUND(AVG(amount) OVER (PARTITION BY user_id ORDER BY order_date, order_id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW),2) ma3 FROM orders ORDER BY user_id, order_date, order_id;","Frames: ROWS counts rows; RANGE uses value distance.",True),
("medium","joins","Products a customer never bought","Every (customer, product) combination the customer has never held a policy for. Count rows only.","CROSS JOIN customers × distinct products, then anti-join.",
"SELECT COUNT(*) AS gaps FROM customers c CROSS JOIN (SELECT DISTINCT product FROM policies) pr WHERE NOT EXISTS (SELECT 1 FROM policies p WHERE p.customer_id=c.customer_id AND p.product=pr.product);","Cross-sell opportunity list — a densification pattern.",False),
("medium","case","Policy tenure category","For each customer: number of policy terms and label 'new' (1), 'renewing' (2), 'loyal' (3+).","COUNT then CASE.",
"SELECT customer_id, COUNT(*) terms, CASE WHEN COUNT(*)=1 THEN 'new' WHEN COUNT(*)=2 THEN 'renewing' ELSE 'loyal' END seg FROM policies GROUP BY customer_id ORDER BY customer_id;","CASE over aggregates is allowed in SELECT.",True),
("medium","ranking","Percentile of claim severity","Each claim's incurred and its percent_rank within cause (2 dp).","PERCENT_RANK().",
"SELECT claim_id, cause, paid_amount+reserve_amount incurred, ROUND(PERCENT_RANK() OVER (PARTITION BY cause ORDER BY paid_amount+reserve_amount),2) pr FROM claims ORDER BY cause, pr, claim_id;","Large-loss flags often use percentile thresholds.",True),
("medium","dates","Policies in force on a date","How many policies were in force on 2025-06-30 (effective <= date < expiration, not cancelled)?","Half-open intervals.",
"SELECT COUNT(*) in_force FROM policies WHERE effective_date<='2025-06-30' AND expiration_date>'2025-06-30' AND status<>'CANCELLED';","Half-open [start, end) avoids double counting renewal days.",False),
("medium","cte","Customers whose first quote bound","Customers whose earliest quote was bound.","ROW_NUMBER by quote_date per customer.",
"WITH f AS (SELECT customer_id, bound, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY quote_date, quote_id) rn FROM quotes) SELECT customer_id FROM f WHERE rn=1 AND bound=1 ORDER BY customer_id;","First-touch analysis.",True),
("medium","aggregation","Orders per user distribution","How many users placed 0,1,2,... complete orders? Include users with 0.","LEFT JOIN users to orders, count per user, then count users per count.",
"WITH c AS (SELECT u.user_id, COUNT(o.order_id) n FROM users u LEFT JOIN orders o ON o.user_id=u.user_id AND o.status='complete' GROUP BY u.user_id) SELECT n AS orders, COUNT(*) users FROM c GROUP BY n ORDER BY n;","Put the status filter in the ON clause, otherwise the LEFT JOIN becomes INNER.",True),
# ---------- HARD ----------
("hard","gaps-islands","Login streaks","Longest consecutive-day login streak per user (dedupe same-day logins).","date minus ROW_NUMBER days is constant within a streak.",
"WITH d AS (SELECT DISTINCT user_id, login_date FROM logins), g AS (SELECT user_id, login_date, julianday(login_date)-ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY login_date) grp FROM d), s AS (SELECT user_id, grp, COUNT(*) len FROM g GROUP BY user_id, grp) SELECT user_id, MAX(len) longest_streak FROM s GROUP BY user_id ORDER BY user_id;","The canonical gaps-and-islands trick. Dedupe first or duplicates break it.",True),
("hard","gaps-islands","Continuous coverage periods","Merge each customer's overlapping/adjacent policy terms into continuous coverage periods (customer_id, start, end).","Flag a new island when start > running MAX(end) of prior rows.",
"WITH t AS (SELECT customer_id, effective_date s, expiration_date e, MAX(expiration_date) OVER (PARTITION BY customer_id ORDER BY effective_date, policy_id ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING) prev_end FROM policies), g AS (SELECT *, SUM(CASE WHEN prev_end IS NULL OR s>prev_end THEN 1 ELSE 0 END) OVER (PARTITION BY customer_id ORDER BY s ROWS UNBOUNDED PRECEDING) isl FROM t) SELECT customer_id, MIN(s) cover_start, MAX(e) cover_end FROM g GROUP BY customer_id, isl ORDER BY customer_id, cover_start;","Interval merging — the insurance version of gaps-and-islands (continuous insurance, lapse detection).",True),
("hard","cohort","Monthly retention cohorts","For users by signup month, count how many placed a complete order in month offset 0,1,2 after signup.","Cohort = strftime signup month; offset = month difference.",
"WITH o AS (SELECT u.user_id, strftime('%Y-%m',u.signup_date) cohort, (CAST(strftime('%Y',o.order_date) AS INT)*12+CAST(strftime('%m',o.order_date) AS INT))-(CAST(strftime('%Y',u.signup_date) AS INT)*12+CAST(strftime('%m',u.signup_date) AS INT)) k FROM users u JOIN orders o ON o.user_id=u.user_id AND o.status='complete') SELECT cohort, COUNT(DISTINCT CASE WHEN k=0 THEN user_id END) m0, COUNT(DISTINCT CASE WHEN k=1 THEN user_id END) m1, COUNT(DISTINCT CASE WHEN k=2 THEN user_id END) m2 FROM o GROUP BY cohort ORDER BY cohort;","Month index = year*12+month avoids date-function differences.",True),
("hard","recursive","Org chart depth","For each employee, their level (CEO=1) and the path of names from the top.","WITH RECURSIVE anchor = manager_id IS NULL.",
"WITH RECURSIVE t(emp_id, name, lvl, path) AS (SELECT emp_id, name, 1, name FROM employees WHERE manager_id IS NULL UNION ALL SELECT e.emp_id, e.name, t.lvl+1, t.path||' > '||e.name FROM employees e JOIN t ON e.manager_id=t.emp_id) SELECT emp_id, name, lvl, path FROM t ORDER BY emp_id;","Recursive CTE = anchor + recursive member joined to the previous iteration.",True),
("hard","recursive","Generate a date spine","Generate every month-start from 2025-01-01 to 2025-12-01 and count complete orders in each (including zero months).","Recursive CTE adding '+1 month'.",
"WITH RECURSIVE m(d) AS (SELECT '2025-01-01' UNION ALL SELECT date(d,'+1 month') FROM m WHERE d<'2025-12-01') SELECT m.d month_start, COUNT(o.order_id) orders FROM m LEFT JOIN orders o ON strftime('%Y-%m',o.order_date)=strftime('%Y-%m',m.d) AND o.status='complete' GROUP BY m.d ORDER BY m.d;","Date spines prevent missing periods in reports (dbt_utils.date_spine in dbt; sequence()/explode in Databricks).",True),
("hard","funnel","Strict ordered funnel","Users who did visit → signup → add_to_cart → purchase in non-decreasing date order. Return user_ids.","Get MIN date per step per user, then compare.",
"WITH s AS (SELECT user_id, MIN(CASE WHEN event_type='visit' THEN event_date END) v, MIN(CASE WHEN event_type='signup' THEN event_date END) su, MIN(CASE WHEN event_type='add_to_cart' THEN event_date END) a, MIN(CASE WHEN event_type='purchase' THEN event_date END) p FROM events GROUP BY user_id) SELECT user_id FROM s WHERE v<=su AND su<=a AND a<=p ORDER BY user_id;","NULL comparisons evaluate unknown → filtered out, which is what we want.",True),
("hard","earned","Earned premium in 2025","Pro-rata earned premium during calendar 2025 for non-cancelled policies, total (2 dp).","Overlap days = max(0, min(exp,'2026-01-01') - max(eff,'2025-01-01')).",
"SELECT ROUND(SUM(premium * MAX(0, julianday(MIN(expiration_date,'2026-01-01'))-julianday(MAX(effective_date,'2025-01-01'))) / (julianday(expiration_date)-julianday(effective_date))),2) AS earned_2025 FROM policies WHERE status<>'CANCELLED';","Interval overlap formula. In SQLite scalar MIN/MAX with 2 args = LEAST/GREATEST elsewhere.",False),
("hard","window","Running count of open claims","For each date a claim is reported or closed... simplified: for each report_date, cumulative number of claims reported and cumulative incurred.","Aggregate per date, then running SUM.",
"WITH d AS (SELECT report_date, COUNT(*) n, SUM(paid_amount+reserve_amount) inc FROM claims GROUP BY report_date) SELECT report_date, SUM(n) OVER (ORDER BY report_date) cum_claims, ROUND(SUM(inc) OVER (ORDER BY report_date),2) cum_incurred FROM d ORDER BY report_date;","Aggregate-then-window avoids tie issues in RANGE frames.",True),
("hard","top-n","Top cause per state by incurred","For each policy state, the cause with the highest total incurred (ties: alphabetical).","Aggregate, then ROW_NUMBER.",
"WITH a AS (SELECT p.state, c.cause, SUM(c.paid_amount+c.reserve_amount) inc FROM claims c JOIN policies p ON p.policy_id=c.policy_id GROUP BY p.state, c.cause), r AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY state ORDER BY inc DESC, cause) rn FROM a) SELECT state, cause, ROUND(inc,2) inc FROM r WHERE rn=1 ORDER BY state;","Top-1 per group after aggregation.",True),
("hard","self-join","Overlapping policies same customer & product","Pairs of policies for the same customer and product whose terms overlap.","Self join with a.policy_id < b.policy_id and interval overlap: a.s < b.e AND b.s < a.e.",
"SELECT a.customer_id, a.policy_id p1, b.policy_id p2 FROM policies a JOIN policies b ON a.customer_id=b.customer_id AND a.product=b.product AND a.policy_id<b.policy_id AND a.effective_date<b.expiration_date AND b.effective_date<a.expiration_date ORDER BY 1,2,3;","Overlap condition is a data-quality test you'd ship as a dbt singular test.",True),
("hard","dedup","Detect near-duplicate claims","Claims on the same policy with the same cause and loss dates within 3 days of each other. Return pairs.","Self join with ABS(julianday diff) <= 3.",
"SELECT a.claim_id c1, b.claim_id c2, a.policy_id FROM claims a JOIN claims b ON a.policy_id=b.policy_id AND a.cause=b.cause AND a.claim_id<b.claim_id AND ABS(julianday(a.loss_date)-julianday(b.loss_date))<=3 ORDER BY 1,2;","Fuzzy dedup is also a fraud signal (duplicate submissions).",True),
("hard","window","Gap between policy terms","For each customer's consecutive policies (by effective_date), days of gap between previous expiration and next effective (negative = overlap).","LAG(expiration_date).",
"WITH x AS (SELECT customer_id, policy_id, effective_date, LAG(expiration_date) OVER (PARTITION BY customer_id ORDER BY effective_date, policy_id) prev_exp FROM policies) SELECT customer_id, policy_id, CAST(julianday(effective_date)-julianday(prev_exp) AS INT) gap_days FROM x WHERE prev_exp IS NOT NULL ORDER BY customer_id, policy_id;","Lapse analysis for retention reporting.",True),
("hard","cohort","Quote-to-bind within 30 days of signup","Per customer signup year, % of customers with a bound quote within 30 days of signup.","Join customers to quotes with date condition in ON; COUNT DISTINCT.",
"SELECT strftime('%Y',c.signup_date) yr, COUNT(DISTINCT c.customer_id) customers, ROUND(100.0*COUNT(DISTINCT q.customer_id)/COUNT(DISTINCT c.customer_id),1) pct FROM customers c LEFT JOIN quotes q ON q.customer_id=c.customer_id AND q.bound=1 AND julianday(q.quote_date)-julianday(c.signup_date) BETWEEN 0 AND 30 GROUP BY yr ORDER BY yr;","Conditions in ON keep the denominator intact.",True),
("hard","window","Median order amount per country","Median complete-order amount per user country.","ROW_NUMBER + COUNT window; average the middle one or two.",
"WITH o AS (SELECT u.country, o.amount, ROW_NUMBER() OVER (PARTITION BY u.country ORDER BY o.amount) rn, COUNT(*) OVER (PARTITION BY u.country) n FROM orders o JOIN users u ON u.user_id=o.user_id WHERE o.status='complete') SELECT country, ROUND(AVG(amount),2) median FROM o WHERE rn IN ((n+1)/2,(n+2)/2) GROUP BY country ORDER BY country;","Portable median; Databricks has percentile_approx / median().",True),
("hard","window","Salary vs dept average and rank gap","For each employee: salary minus dept average (0 dp) and difference to the next higher salary in dept (NULL for top).","AVG OVER and LAG over salary DESC.",
"SELECT name, dept, salary, ROUND(salary-AVG(salary) OVER (PARTITION BY dept)) vs_avg, LAG(salary) OVER (PARTITION BY dept ORDER BY salary DESC, emp_id)-salary gap_to_next FROM employees ORDER BY dept, salary DESC;","Multiple windows in one SELECT.",True),
("hard","pivot","Claims development style triangle","Accident year (loss_date year) × report lag bucket (0-1d, 2-7d, 8-30d, 31+d) claim counts.","CASE bucketing inside conditional aggregation.",
"SELECT strftime('%Y',loss_date) ay, SUM(CASE WHEN lag<=1 THEN 1 ELSE 0 END) d0_1, SUM(CASE WHEN lag BETWEEN 2 AND 7 THEN 1 ELSE 0 END) d2_7, SUM(CASE WHEN lag BETWEEN 8 AND 30 THEN 1 ELSE 0 END) d8_30, SUM(CASE WHEN lag>30 THEN 1 ELSE 0 END) d31p FROM (SELECT loss_date, julianday(report_date)-julianday(loss_date) lag FROM claims) GROUP BY ay ORDER BY ay;","Report-lag shapes reveal IBNR risk.",True),
("hard","cte","Customers whose every claim is closed","Customers with at least one claim and all claims CLOSED.","GROUP BY + HAVING with conditional counts.",
"SELECT p.customer_id FROM claims c JOIN policies p ON p.policy_id=c.policy_id GROUP BY p.customer_id HAVING SUM(CASE WHEN c.status<>'CLOSED' THEN 1 ELSE 0 END)=0 ORDER BY p.customer_id;","'For all' questions → HAVING with a count of violations = 0.",True),
("hard","sessionize","Order sessions","Group each user's orders into 'sessions' where a new session starts if >30 days since the previous order. Count sessions per user.","LAG + flag + running SUM.",
"WITH x AS (SELECT user_id, order_date, CASE WHEN julianday(order_date)-julianday(LAG(order_date) OVER (PARTITION BY user_id ORDER BY order_date, order_id))<=30 THEN 0 ELSE 1 END new_s FROM orders) SELECT user_id, SUM(new_s) sessions FROM x GROUP BY user_id ORDER BY user_id;","Sessionization = gaps-and-islands with a threshold.",True),
("hard","window","First and last premium per customer","Per customer: first policy premium, latest policy premium, number of terms.","FIRST_VALUE / LAST_VALUE (mind the frame!).",
"SELECT DISTINCT customer_id, FIRST_VALUE(premium) OVER w first_prem, LAST_VALUE(premium) OVER w last_prem, COUNT(*) OVER (PARTITION BY customer_id) terms FROM policies WINDOW w AS (PARTITION BY customer_id ORDER BY effective_date ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) ORDER BY customer_id;","LAST_VALUE with the default frame returns the current row — the #1 window gotcha.",True),
("hard","joins","Customers quoted but never bound any product","Customer names with ≥2 quotes and zero binds and no policies.","Aggregate quotes + anti-join policies.",
"SELECT c.name FROM customers c JOIN quotes q ON q.customer_id=c.customer_id GROUP BY c.customer_id, c.name HAVING COUNT(*)>=2 AND SUM(q.bound)=0 AND NOT EXISTS (SELECT 1 FROM policies p WHERE p.customer_id=c.customer_id) ORDER BY c.name;","Combine HAVING with correlated NOT EXISTS. Empty result is a valid answer — know why.",True),
("hard","dates","Weekly active users with 7-day rolling","Per login date: distinct users that day and distinct users in the trailing 7 days.","Self join logins on date window, COUNT DISTINCT.",
"WITH d AS (SELECT DISTINCT login_date FROM logins) SELECT d.login_date, COUNT(DISTINCT CASE WHEN l.login_date=d.login_date THEN l.user_id END) dau, COUNT(DISTINCT l.user_id) wau7 FROM d JOIN logins l ON julianday(l.login_date) BETWEEN julianday(d.login_date)-6 AND julianday(d.login_date) GROUP BY d.login_date ORDER BY d.login_date;","COUNT DISTINCT over a rolling window isn't supported as a window function in most engines — use a range self join.",True),
]
